#include <stdio.h>

int main() {
    int n, p, t;
    scanf("%d", &n);
    scanf("%d", &p);
    scanf("%d", &t);

    if (n == 1) {
        printf("0\n");
        return 0;
    }

    int period = 2 * (n - 1);
    int x = (p + t) % period;

    int ans;
    if (x <= n - 1) {
        ans = x;
    } else {
        ans = period - x;
    }

    printf("%d\n", ans);
    return 0;
}
